#!/usr/bin/env bash
# Sync the generated CRDs and RBAC rules into the shop-operator Helm chart (research R8, R14).
#
#   hack/sync-chart.sh [CHART_DIR]      default: ../helm-charts/charts/shop-operator
#
# Writes CHART_DIR/templates/crds.yaml (all CRDs from config/crd/bases, annotated
# helm.sh/resource-policy: keep so uninstalling the chart never deletes Shops) and
# CHART_DIR/templates/rbac.yaml (ClusterRole from config/rbac/role.yaml, leader-election Role
# from config/rbac/leader_election_role.yaml, plus their bindings). Run `make manifests` first.
# The generated files are committed to helm-charts through a normal PR.
set -euo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")/.."
chart="${1:-../helm-charts/charts/shop-operator}"
[[ -f "$chart/Chart.yaml" ]] || { echo "ERROR: $chart is not a chart directory" >&2; exit 3; }
command -v yq >/dev/null || { echo "ERROR: yq v4 not found" >&2; exit 2; }
yq --version | grep -q 'version v4' || { echo "ERROR: yq v4 required" >&2; exit 2; }

rev="$(git rev-parse --short HEAD 2>/dev/null || echo unknown)"
header="# GENERATED by shop-operator/hack/sync-chart.sh (shop-operator@$rev). Do not edit by hand."

# --- CRDs ---------------------------------------------------------------------------------
crds="$chart/templates/crds.yaml"
{
  echo "$header"
  first=true
  for f in config/crd/bases/*.yaml; do
    $first || echo "---"
    first=false
    yq eval '.metadata.annotations."helm.sh/resource-policy" = "keep"' "$f"
  done
} > "$crds"
if grep -q '{{' "$crds"; then
  echo "ERROR: a CRD contains '{{', which Helm would try to template; escape it first" >&2
  exit 1
fi

# --- RBAC ---------------------------------------------------------------------------------
indent_rules() { yq eval '.rules' "$1"; }
cat > "$chart/templates/rbac.yaml" <<YAML
$header
# Cluster-wide because Shops live in user namespaces created at runtime (plan Complexity
# Tracking). Rules come from the +kubebuilder:rbac markers; no wildcards.
apiVersion: rbac.authorization.k8s.io/v1
kind: ClusterRole
metadata:
  name: {{ include "shop-operator.fullname" . }}-manager
  labels:
    {{- include "shop-operator.labels" . | nindent 4 }}
rules:
$(indent_rules config/rbac/role.yaml)
---
apiVersion: rbac.authorization.k8s.io/v1
kind: ClusterRoleBinding
metadata:
  name: {{ include "shop-operator.fullname" . }}-manager
  labels:
    {{- include "shop-operator.labels" . | nindent 4 }}
roleRef:
  apiGroup: rbac.authorization.k8s.io
  kind: ClusterRole
  name: {{ include "shop-operator.fullname" . }}-manager
subjects:
  - kind: ServiceAccount
    name: {{ include "shop-operator.fullname" . }}
    namespace: {{ .Release.Namespace }}
---
# Leader election, limited to the release namespace.
apiVersion: rbac.authorization.k8s.io/v1
kind: Role
metadata:
  name: {{ include "shop-operator.fullname" . }}-leader-election
  namespace: {{ .Release.Namespace }}
  labels:
    {{- include "shop-operator.labels" . | nindent 4 }}
rules:
$(indent_rules config/rbac/leader_election_role.yaml)
---
apiVersion: rbac.authorization.k8s.io/v1
kind: RoleBinding
metadata:
  name: {{ include "shop-operator.fullname" . }}-leader-election
  namespace: {{ .Release.Namespace }}
  labels:
    {{- include "shop-operator.labels" . | nindent 4 }}
roleRef:
  apiGroup: rbac.authorization.k8s.io
  kind: Role
  name: {{ include "shop-operator.fullname" . }}-leader-election
subjects:
  - kind: ServiceAccount
    name: {{ include "shop-operator.fullname" . }}
    namespace: {{ .Release.Namespace }}
YAML

echo "wrote $crds ($(grep -c '^kind: CustomResourceDefinition' "$crds") CRDs) and $chart/templates/rbac.yaml"
